INSERT INTO note VALUES (1,1,1,'成都春熙路必吃川菜｜川味小厨探店','周末和朋友去打卡，水煮鱼麻辣鲜香，鱼片很嫩，强烈推荐！人均 70 左右，性价比很高。',NULL,NULL,137,2,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0);
INSERT INTO note VALUES (2,2,2,'杭州文三路隐藏的杭帮菜馆','东坡肉真的入口即化，环境古色古香，适合家庭聚餐。',NULL,NULL,98,2,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0);
INSERT INTO note VALUES (3,3,3,'北京南锣鼓巷铜锅涮肉攻略','手切鲜羊肉必点，麻酱小料是灵魂，建议提前排队。',NULL,NULL,211,1,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0);
INSERT INTO note VALUES (4,2,4,'广州早茶｜虾饺皇天花板','虾饺皮薄到透光，一口一个，配上普洱刚刚好。',NULL,NULL,74,1,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0);
INSERT INTO note VALUES (5,3,6,'上海静安深夜食堂｜日式居酒屋','三文鱼厚切八片，鸡皮串外酥里嫩，营业到凌晨两点。',NULL,NULL,156,40,1,'2026-10-24 13:14:06','2026-10-24 13:14:06',0);
