INSERT INTO note VALUES (3001,1,101,'藏在科华北路的川菜馆，毛血旺太顶了','周末去打卡，毛血旺料很足，鸭血嫩，午餐肉厚切，配米饭能吃两碗。',NULL,NULL,30,2,1,'2026-10-23 14:35:37','2026-10-23 14:35:37',0);
