INSERT INTO note VALUES (3003,3,103,'北京护国寺街的炸酱面','面条筋道，酱香浓郁，配一碟腊八蒜刚刚好。',NULL,NULL,56,12,1,'2026-10-21 14:35:37','2026-10-21 14:35:37',0);
